#include DUF_SOURCE
#include <algorithm>
#include <bit>
#include <chrono>
#include <cstdio>
#include <cstdint>
#include <limits>
#include <random>
#include <string>
#include <vector>
using Clock=std::chrono::steady_clock;
int main(int argc,char** argv) {
 const std::string mode=argc>1?argv[1]:"mixed";
 const int n=argc>2?std::stoi(argv[2]):200000;
 const int repeats=n<100?4000:1;
 std::mt19937 rng(93838);
 std::vector<int> keys(n);
 for(int i=0;i<n;++i)keys[i]=i;
 const bool sparse=mode=="sparse_add"||mode=="mixed"||mode=="read_sparse"||mode=="contains"||mode=="callbacks"||mode=="groups"||mode=="clear";
 if(sparse) {
  for(int& key:keys)key=std::bit_cast<int>(std::uint32_t(rng()));
  if(n>=3){keys[0]=std::numeric_limits<int>::min();keys[1]=std::numeric_limits<int>::max();keys[2]=-1;}
 }
 std::vector<std::pair<int,int>> queries(n*3);
 for(auto& [x,y]:queries){x=rng()%n;y=rng()%n;}
 std::uint64_t checksum=0,nodes=0;std::int64_t ns=0;
 if(mode=="read_dense"||mode=="read_sparse"||mode=="contains"||mode=="groups"||mode=="clear") {
  DynamicUnionFind uf(n);
  for(int key:keys)uf.add(key);
  for(int i=1;i<n;i+=2)uf.unite(keys[i-1],keys[i]);
  const auto start=Clock::now();
  if(mode=="read_dense"||mode=="read_sparse") {
   const int rounds=n<100?4000:4;
   for(int rep=0;rep<rounds;++rep)for(const auto& [x,y]:queries){checksum+=uf.same(keys[x],keys[y]);checksum+=uf.size(keys[x]);checksum+=std::uint32_t(uf.find(keys[y]));}
  } else if(mode=="contains") {
   const int rounds=n<100?4000:4;
   for(int rep=0;rep<rounds;++rep)for(const auto& [x,y]:queries){checksum+=uf.contains(keys[x]);checksum+=uf.contains(std::bit_cast<int>(std::uint32_t(keys[y])^0xa5a5a5a5u));}
  } else if(mode=="groups") {
   const int rounds=n<100?2000:3;
   for(int rep=0;rep<rounds;++rep){auto groups=uf.groups();for(auto& g:groups)for(int key:g)checksum+=std::uint32_t(key);checksum+=groups.size();}
  } else {
   const int rounds=n<100?4000:3;
   for(int rep=0;rep<rounds;++rep){uf.clear();for(int key:keys)checksum+=uf.add(key);checksum+=uf.node_count()+uf.component_count();}
  }
  ns=std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-start).count();nodes=uf.node_count();
 } else {
  const auto start=Clock::now();
  for(int rep=0;rep<repeats;++rep) {
   DynamicUnionFind uf;
   if(mode=="dense_add"||mode=="sparse_add")for(int key:keys){checksum+=uf.add(key);checksum+=uf.contains(key);}
   else if(mode=="star")for(int i=1;i<n;++i){checksum+=uf.unite(keys[0],keys[i]);checksum+=uf.same(keys[0],keys[i]);checksum+=uf.size(keys[i]);}
   else if(mode=="balanced"){
    for(int key:keys)uf.add(key);
    for(int step=1;step<n;step*=2)for(int i=step;i<n;i+=step*2)checksum+=uf.unite(keys[i-step],keys[i]);
    for(int key:keys){checksum+=std::uint32_t(uf.find(key));checksum+=uf.size(key);}
   } else if(mode=="self")for(int key:keys){checksum+=uf.same(key,key);checksum+=uf.unite(key,key);checksum+=uf.size(key);}
   else if(mode=="callbacks")for(const auto& [x,y]:queries){checksum+=uf.unite(keys[x],keys[y],[&](int a,int b){checksum+=std::uint32_t(a)+std::uint32_t(b);});checksum+=uf.size(keys[y]);}
   else for(int i=0;i<n*3;++i){const auto [x,y]=queries[i];switch(i%6){case 0:checksum+=uf.unite(keys[x],keys[y]);break;case 1:checksum+=uf.same(keys[x],keys[y]);break;case 2:checksum+=uf.size(keys[x]);break;case 3:checksum+=std::uint32_t(uf.find(keys[y]));break;case 4:checksum+=uf.add(keys[x]);break;case 5:checksum+=uf.contains(keys[y]);break;}}
   checksum+=uf.component_count();nodes+=uf.node_count();
  }
  ns=std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-start).count();
 }
 std::printf("%jd %ju %ju\n",std::intmax_t(ns),std::uintmax_t(checksum),std::uintmax_t(nodes));
}

