#include DUF_SOURCE
#include <bit>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <random>
#include <string>
#include <vector>
int main(int argc,char** argv) {
 const int n=argc>1?std::stoi(argv[1]):32;
 const int repeats=n<100?200000:20;
 std::mt19937 rng(93838);
 std::vector<int> keys(n);
 for(int& key:keys)key=std::bit_cast<int>(std::uint32_t(rng()));
 if(n>=3){keys[0]=std::numeric_limits<int>::min();keys[1]=std::numeric_limits<int>::max();keys[2]=-1;}
 DynamicUnionFind uf(n);
 for(int key:keys)uf.add(key);
 for(int i=1;i<n;i+=2)uf.unite(keys[i-1],keys[i]);
 std::uint64_t checksum=0;
 const auto start=std::chrono::steady_clock::now();
 for(int rep=0;rep<repeats;++rep) {
  const auto groups=uf.groups();
  for(const auto& g:groups)for(int key:g)checksum+=std::uint32_t(key);
  checksum+=groups.size();
 }
 const auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-start).count();
 std::printf("%jd %ju %zu\n",std::intmax_t(ns),std::uintmax_t(checksum),uf.node_count());
}

