from pathlib import Path
import subprocess,json,fcntl,statistics,hashlib,os
p=Path(__file__).parent;builds=[];rows=[];tags=['baseline','control','selected'];seeds=[83,1447,27189,93838,389011,1207019,9999839]
for tag in ['baseline','selected']:
 source=p/(tag+'_seeded.cpp');binary=p/('gcc_'+tag+'_seeded');cmd=['taskset','-c','4','g++','-std=c++23','-O2','-march=native','-DSKIP_RUNTIME_CHECKS','-Wall','-Wextra','-Wpedantic','-DDUF_SOURCE="'+str(source)+'"',str(p/'api.cpp'),'-o',str(binary)];v=subprocess.run(cmd,capture_output=True,text=True);assert not v.returncode,v.stderr;builds.append(dict(tag=tag,command=cmd,warnings=v.stderr,source_sha256=hashlib.sha256(source.read_bytes()).hexdigest()))
control=p/'gcc_control_seeded';control.write_bytes((p/'gcc_baseline_seeded').read_bytes());control.chmod(0o755)
print('built controlled-seed API benchmark',flush=True)
with open('/tmp/atcoder_full_performance_20261018/benchmark.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for n in [32,200000]:
  for mode in ['dense_add','sparse_add','star','balanced','self','mixed','read_dense','read_sparse','contains','callbacks','groups','clear']:
   for rep in range(-1,7):
    order=tags[:];i=(rep+1)%len(order);order=order[i:]+order[:i]
    if rep%2:order.reverse()
    seed=seeds[max(rep,0)];env=os.environ.copy();env['DUF_BENCH_SEED']=str(seed)
    for tag in order:
     v=subprocess.run(['taskset','-c','14',str(p/('gcc_'+tag+'_seeded')),mode,str(n)],capture_output=True,text=True,env=env);assert not v.returncode,v.stderr;ns,checksum,nodes=map(int,v.stdout.split())
     if rep>=0:rows.append(dict(n=n,mode=mode,rep=rep,seed=seed,tag=tag,ns=ns,checksum=checksum,nodes=nodes))
   rr=[x for x in rows if x['n']==n and x['mode']==mode];assert len({x['checksum']for x in rr})==1;assert len({x['nodes']for x in rr})==1
   med={tag:statistics.median(x['ns']for x in rr if x['tag']==tag)/1e6 for tag in tags};ratios=[]
   for rep in range(7):
    sample={x['tag']:x['ns']for x in rr if x['rep']==rep};ratios.append(sample['selected']/sample['baseline'])
   print(n,mode,{k:round(v,4)for k,v in med.items()},'pairedmedian',round((statistics.median(ratios)-1)*100,2),flush=True);(p/'seeded_api_results.json').write_text(json.dumps(dict(builds=builds,seeds=seeds,method='Only test header initial_salt clock changed to getenv/strtoull(DUF_BENCH_SEED), mix(seed)|1 retained; seed paired within replicate; production binaries untouched.',rows=rows),indent=2))

